    return max(int(num) for num in numbers)

def get_inv_count(arr):
    inv_count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            if arr[i] > arr[j]:
                inv_count += 1
    return inv_count

def remove_negs(numbers):
    new_list = []
    for number in numbers:
        if number >= 0:
            new_list.append(number)
    return new_list

def count_list(l):
    if l:
        return 1 + count_list(l[1:])
    else:
        return 0

